export const BODY: string = "\n<p>بیس تصویروں کو ایک ایک کر کے سائز بدلنا سست، غلطی والا کام ہے۔ بیس بار لکھا گیا ایک ہی سائز ٹائپنگ غلطیوں کو دعوت دیتا ہے، اور بیس فائلیں ایک ایک کر کے ڈاؤن لوڈ کرنے سے دوپہر ضائع ہوتی ہے۔ انہیں بیچ کے طور پر سائز بدلنے میں چند منٹ لگتے ہیں اور ہر تصویر پر ایک ہی ترتیبات لاگو ہوتی ہیں۔</p>\n<p>یہ رہنما <a href=\"/ur/bulk-tasveer-resize-karein/\">بلک تصویر ری سائزر</a> پر عمل بتاتا ہے، فولڈر تیار کرنے سے لے کر ZIP ڈاؤن لوڈ کرنے تک۔ اس میں چار حکمت عملیاں، پری سیٹ، کوالٹی ترتیبات، اور وہ جانچیں شامل ہیں جو خراب بیچ کو استعمال سے پہلے پکڑتی ہیں۔</p>\n<p>آخر تک آپ جان جائیں گے کہ مصنوعات شوٹ، بلاگ فولڈر یا سوشل سیٹ کو ایک پاس میں کیسے سائز بدلیں۔ ہر حکمت عملی کے پیچھے تصورات کے لیے <a href=\"/ur/blog/bulk-tasveer-resizer-rehnumai/\">Bulk Image Resizer: Complete Guide</a> پڑھیں۔</p>\n<h2 id=\"resize-a-batch-in-six-steps\">چھ مراحل میں بیچ سائز بدلیں</h2>\n<p>بیچ عمل ہر بار انہی چھ مراحل پر چلتا ہے۔ انہیں ایک بار سیکھ لیں اور اس کے بعد ہر فولڈر معمول بن جاتا ہے، چاہے اس میں پانچ مصنوعات شاٹ ہوں یا پچاس چھٹی کی تصویریں۔</p>\n<ol>\n<li>کئی تصویریں بیچ قطار میں ڈالیں: 25 MB تک JPG، PNG، WebP، HEIC، GIF، BMP یا SVG فائلوں کا کوئی بھی مرکب اپ لوڈ کریں۔</li>\n<li>بیچ سائز بدلنے کی حکمت عملی چنیں: ملے جلے رخ کے لیے Fit Max W by H، مقررہ کالم کے لیے Uniform Width، سخت گرڈ کے لیے Exact W by H، یا یکساں اسکیلنگ کے لیے Percentage چنیں۔</li>\n<li>ہدف ابعاد یا پری سیٹ طے کریں: 1 سے 12,000 px تک پکسل لکھیں، یا Full HD 1920px، Blog 1200px، E-commerce 1000 بہ 1000، یا Thumbnail 600px کلک کریں۔</li>\n<li>اوپر بڑھانے سے تحفظ اور فٹ ترتیب دیں: Do not enlarge smaller images کو چیک رکھیں، یا Exact W by H چننے پر Contain، Cover یا Stretch چنیں۔</li>\n<li>آؤٹ پٹ فارمیٹ، کوالٹی اور میٹ چنیں: Original رکھیں یا JPG، PNG یا WebP میں بدلیں، کوالٹی 10 سے 100 فیصد طے کریں، اور JPG کے لیے میٹ رنگ چنیں۔</li>\n<li>بیچ چلائیں اور ZIP ڈاؤن لوڈ کریں: ہر کارڈ کے پرانے سے نئے ابعاد کا جائزہ لیں اور bulk_resized_compressmypic.zip محفوظ کرنے کے لیے Download All (ZIP) پر کلک کریں۔</li>\n</ol>\n<h2 id=\"prepare-your-batch\">پہلے اپنا بیچ تیار کریں</h2>\n<p>اچھے بیچ ٹول کھلنے سے پہلے شروع ہوتے ہیں۔ تصویریں ایک فولڈر میں جمع کریں اور جانچیں کہ وہ سب ایک ہی کام کی ہیں: ایک مصنوعات، ایک بلاگ پوسٹ، یا ایک سوشل مہم۔ کام ملانے والا بیچ ایسی ترتیبات کے ساتھ ختم ہوتا ہے جو کسی کو سوٹ نہیں کرتیں۔</p>\n<p>سائز بدلنے سے پہلے اصل جانچیں۔ دھندلا ماخذ کسی بھی سائز پر دھندلا رہتا ہے، اور بیچ خراب تصویر درست نہیں کر سکتا۔ فولڈر سے نقل اور آزمائشی شاٹ ہٹا دیں، کیونکہ ہر اضافی فائل جانچنے والا ایک اور کارڈ اور ZIP میں ایک اور فائل ہے۔</p>\n<p>اپ لوڈ سے پہلے ہدف سائز نوٹ کریں۔ مصنوعات گرڈ 1000 بہ 1000 چاہتا ہے، بلاگ فولڈر 1200 چوڑا چاہتا ہے، اور تھمب نیل سیٹ 600 چاہتا ہے۔ ہدف لکھنے سے کام تیز رہتا ہے اور بیچ دوبارہ چلانے سے بچتا ہے کیونکہ سائز اندازہ تھا۔</p>\n<h2 id=\"choose-a-strategy\">بیچ کے لیے حکمت عملی چنیں</h2>\n<p>حکمت عملی اہم فیصلہ ہے، اور یہ منزل پر منحصر ہے۔ Fit Max ہر تصویر کو کراپ یا کھینچے بغیر باؤنڈنگ ڈبے کے اندر فٹ کرتا ہے، جو ملے جلے فولڈر کو سوٹ کرتا ہے۔ Uniform Width ہر تصویر کو مقررہ کالم کے لیے ایک ہی چوڑائی دیتا ہے۔ Exact سخت گرڈ کے لیے ایک جیسے ابعاد مجبور کرتا ہے۔</p>\n<p>Percentage سب سے آسان انتخاب ہے جب فولڈر کو صرف چھوٹا ہونا ہے۔ 50 فیصد چنیں اور ہر تصویر ہر سمت میں آدھی ہو جاتی ہے، سیٹ میں نسبتی سائز رکھتے ہوئے۔ اسے کوئی ابعاد اور رخ کے بارے میں کوئی سوچ نہیں چاہیے، اسی لیے یہ کیمرہ فولڈر کی فوری صفائی کو سوٹ کرتا ہے۔</p>\n<p>جب آپ کو یقین نہ ہو تو 1200 بہ 1200 پر Fit Max سے شروع کریں۔ یہ ملے جلے بیچ کے لیے محفوظ ترین حکمت عملی ہے، اور یہ سب سے عام ویب ضرورت سے میل کھاتی ہے: تصویریں جو بغیر بگاڑ کے زیادہ سے زیادہ ڈبے کے اندر فٹ ہوں۔ آپ دوبارہ اپ لوڈ کیے بغیر دوسری حکمت عملی کے ساتھ بیچ دوبارہ چلا سکتے ہیں۔</p>\n<h2 id=\"set-a-preset-or-type-the-size\">پری سیٹ طے کریں یا سائز لکھیں</h2>\n<p>چار فوری پری سیٹ سب سے عام بیچ سائز پورا کرتے ہیں۔ Full HD 1920px چوڑی اسکرینوں کے لیے 1920 بہ 1080 بھرتا ہے، Blog 1200px مواد تصویروں کے لیے 1200 بہ 1200 ڈبہ طے کرتا ہے، E-commerce 1000 بہ 1000 مربع مصنوعات سائز طے کرتا ہے، اور Thumbnail 600px پیش نظارہ کے لیے 600 بہ 600 طے کرتا ہے۔</p>\n<p>پری سیٹ نقطہ آغاز ہیں، مقفل انتخاب نہیں۔ ایک کلک کرنے کے بعد آپ 12,000 پکسل تک کسی بھی پکسل فیلڈ کو ہاتھ سے ایڈجسٹ کر سکتے ہیں، اس لیے قریب پری سیٹ کو اس بالکل سائز تک ٹیون کیا جا سکتا ہے جو پلیٹ فارم مانگتا ہے۔ یہ لچک اہم ہے جب مارکیٹ پلیس غیر معمولی ابعاد مانگے۔</p>\n<p>پری سیٹ سے باہر سائز کے لیے عدد سیدھے لکھیں۔ سوشل سائز جیسے مربع پوسٹ کے لیے 1080 بہ 1080 یا کہانی کے لیے 1080 بہ 1920 ٹول کے لیے صرف پکسل قیمتیں ہیں، اور فیلڈ ہر طرف 1 سے 12,000 پکسل تک کوئی بھی سائز قبول کرتے ہیں۔</p>\n<h2 id=\"set-quality-and-format\">کوالٹی اور فارمیٹ طے کریں</h2>\n<p>فارمیٹ اور کوالٹی طے کرتے ہیں کہ سائز بدلی فائلیں کیسے محفوظ ہوتی ہیں، اور وہ ابعاد جتنی ہی اہم ہیں۔ Original فارمیٹ رکھنا محتاط انتخاب ہے: سائز بدلی تصویریں وہی فارمیٹ رکھتی ہیں جس میں وہ آئی تھیں، اور شفافیت بالکل ویسے ہی برتاؤ کرتی ہے جیسے پہلے۔</p>\n<p>اسی پاس میں بدلنے سے دوسرا کام بچتا ہے۔ ملے جلے JPG اور PNG فائلوں کا فولڈر یکساں طور پر WebP کے طور پر نکل سکتا ہے، جو ویب کے لیے چھوٹا ہے، یا مارکیٹ پلیس کے لیے 85 فیصد کوالٹی پر یکساں طور پر JPG کے طور پر نکل سکتا ہے۔ ری سائزر اسکیل کرتے ہوئے بدلتا ہے، اس لیے ایک کلک دونوں مراحل کرتا ہے۔</p>\n<p>بیچ میں تصویروں کے لیے 85 فیصد کے قریب کوالٹی بہترین نقطہ ہے۔ یہ کنارے تیز اور گریڈینٹ صاف رکھتی ہے جبکہ فائل سائز تیزی سے کاٹتی ہے۔ اسے 65 سے 75 فیصد کی طرف صرف تب کم کریں جب فائلیں بہت چھوٹی ہونی چاہییں، اور پرنٹ تیاری کے لیے 95 سے 100 فیصد کی طرف بڑھائیں۔</p>\n<h2 id=\"check-the-results\">ڈاؤن لوڈ سے پہلے نتائج جانچیں</h2>\n<p>چالیس تصویروں پر لاگو ایک خراب ترتیب چالیس خراب تصویریں ہیں، اس لیے ڈاؤن لوڈ سے پہلے بیچ جانچیں۔ ہر کارڈ پرانے اور نئے پکسل ابعاد دکھاتا ہے، اس لیے غلط سائز ZIP بننے سے پہلے ہی فوراً نظر آتا ہے۔</p>\n<p>پہلے اور بعد کا ویور کھولنے کے لیے کسی بھی تھمب نیل یا Compare بٹن پر کلک کریں۔ تیز کنارے، پڑھنے کے قابل متن اور صحیح تناسب کی تصدیق کے لیے تقسیم کرنے والا تصویر پر گھسیٹیں۔ پہلے چند کارڈ احتیاط سے جانچیں، پھر باقی کو جگہ جگہ جانچیں، خاص طور پر زیادہ تر منظر بیچ میں کوئی پورٹریٹ۔</p>\n<p>تین عام بیچ مسائل دیکھیں: Stretch کے ساتھ Exact سے کھینچی ہوئی تصویر، بڑا کرنے سے نرم تصویر، اور PNG تبدیلی سے بھاری فائل۔ تینوں ایک ترتیب بدل کر اور Bulk Resize دوبارہ کلک کر کے درست ہو سکتے ہیں، فائلیں دوبارہ اپ لوڈ کیے بغیر۔</p>\n<h2 id=\"download-the-zip\">ZIP ڈاؤن لوڈ کریں</h2>\n<p>جب نتائج درست لگیں تو bulk_resized_compressmypic.zip محفوظ کرنے کے لیے Download All (ZIP) پر کلک کریں۔ یہ قطار کی ہر کامیاب سائز بدلی فائل کو ایک آرکائیو میں پیک کرتا ہے، آپ کے براؤزر میں مقامی طور پر بنایا گیا، اندر صاف اور پہچانی جانے والی فائل ناموں کے ساتھ۔</p>\n<p>اس کے مواد کہیں اپ لوڈ کرنے سے پہلے ZIP کھولیں۔ جانچیں کہ ہر متوقع فائل اندر ہے، نام سمجھ آتے ہیں، اور جگہ جگہ جانچی گئی تصویر درست سائز پر کھلتی ہے۔ تیس سیکنڈ کی جانچ مارکیٹ پلیس اپ لوڈ کے درمیان گم شدہ فائل دریافت کرنے سے بہتر ہے۔</p>\n<p>واضح نام والے فولڈر میں ان زپ کریں، جیسے product-photos-1000px، سائز بدلی فائلوں کو اصل کے ساتھ ملانے کی بجائے۔ دو سیٹ الگ رکھنے سے اصل کو غلطی سے اپ لوڈ کرنے، یا سائز بدلی فائل کو بڑی فائل سے اوور رائٹ کرنے کی عام غلطی رکتی ہے۔</p>\n<h2 id=\"mixed-orientations-in-a-batch\">بیچ میں ملے جلے رخ</h2>\n<p>زیادہ تر حقیقی بیچ منظر اور پورٹریٹ تصویریں ملاتے ہیں، اور حکمت عملی طے کرتی ہے کہ اس مرکب کو کیسے سنبھالا جائے۔ Fit Max بہترین پہلے سے طے شدہ ہے: 4000 بہ 2000 منظر 1200 بہ 600 بن جاتا ہے اور 2000 بہ 4000 پورٹریٹ اسی 1200 بہ 1200 ڈبے کے اندر 600 بہ 1200 بن جاتا ہے، بغیر کچھ کراپ کیے۔</p>\n<p>Uniform Width ملے جلے بیچ کو بھی خوبصورتی سے سنبھالتا ہے، ہر تصویر کو ایک ہی چوڑائی دیتے ہوئے جبکہ ہر اونچائی اپنے تناسب کی پیروی کرتی ہے۔ یہ بلاگ کالم یا گیلری سلسلے کو سوٹ کرتا ہے جہاں چوڑائی مقرر ہے اور اونچائی آزادانہ بدل سکتی ہے۔</p>\n<p>ملے جلے بیچ کے لیے بالکل ابعاد مشکل صورت ہیں، کیونکہ ایک فریم سمجھوتے کے بغیر دو شکلوں میں فٹ نہیں ہو سکتا۔ Contain پوری تصویر پیڈنگ کے ساتھ رکھتا ہے، Cover کنارے تراش کر فریم بھرتا ہے، اور Stretch بگاڑتا ہے۔ جان بوجھ کر چنیں، اور ڈاؤن لوڈ سے پہلے پورٹریٹ اور منظر کارڈ جانچیں۔</p>\n<h2 id=\"resize-a-product-shoot\">مصنوعات شوٹ سائز بدلیں</h2>\n<p>مصنوعات شوٹ کلاسک بلک سائز بدلنے کا کام ہے: ایک ہی چیزوں کی درجنوں تصویریں، سب کو مارکیٹ پلیس کے لیے ایک ہی مربع سائز چاہیے۔ Cover کے ساتھ 1000 بہ 1000 پر Exact W by H استعمال کریں، تاکہ لسٹنگ گرڈ میں ہر ٹائل ایک جیسی اور کنارے تک بھری ہو۔</p>\n<p>بیچ چلانے سے پہلے جانچیں کہ موضوع ہر شاٹ میں مرکز میں ہے۔ Cover اطراف سے اضافی تراشتا ہے، اس لیے فریم کے کنارے کے قریب مصنوعات کونہ کھو سکتی ہے۔ چلانے سے پہلے تھمب نیل کی فوری نظر ان شاٹ کو پکڑتی ہے جنہیں دوبارہ فریم کرنا ہے۔</p>\n<p>شوٹ کے لیے no-upscale تحفظ آن رکھیں، تاکہ چھوٹے تفصیلی شاٹ پورے 1000 پکسل تک نہ کھینچے جائیں۔ 600 پکسل پر لیا گیا قریبی شاٹ 600 پکسل اور تیز رہنا چاہیے، گرڈ میں نرم 1000 پکسل تصویر بننے کی بجائے۔</p>\n<h2 id=\"resize-a-blog-folder\">بلاگ فولڈر سائز بدلیں</h2>\n<p>بلاگ فولڈر ایک جیسے ابعاد کی بجائے مستقل چوڑائی چاہتا ہے۔ 1200 بہ 1200 پر Fit Max یا 1200 پکسل پر Uniform Width استعمال کریں، تاکہ ہر مواد تصویر 1200 چوڑی ہو اور ہر ایک اپنی قدرتی اونچائی رکھے۔ مضمون کالم صاف رہتا ہے اور تصویریں سچی رہتی ہیں۔</p>\n<p>بلاگ تصویروں میں عام طور پر ایک فولڈر میں اسکرین شاٹ، تصویریں اور گرافکس شامل ہوتے ہیں، اس لیے آؤٹ پٹ فارمیٹ Original پر رکھیں یا پورا بیچ WebP میں بدلیں۔ 80 سے 85 فیصد کوالٹی پر WebP اسکرین شاٹ کو پڑھنے کے قابل اور تصویروں کو ہلکا رکھتا ہے، جو بلاگ کو بالکل چاہیے۔</p>\n<p>بیچ میں اسکرین شاٹ کو اضافی احتیاط سے جانچیں۔ اسکرین شاٹ میں متن تصویر سے پہلے نرمی دکھاتا ہے، اس لیے ایک اسکرین شاٹ کارڈ پر Compare منظر کھولیں اور اس کا سب سے چھوٹا متن پڑھیں۔ اگر پڑھنا مشکل ہو تو کوالٹی بڑھائیں یا ہدف چوڑائی بڑھائیں۔</p>\n<h2 id=\"resize-a-social-set\">سوشل سیٹ سائز بدلیں</h2>\n<p>سوشل سیٹ کئی پلیٹ فارم کے لیے سائز بدلی ایک تصویر ہے، یا ایک پلیٹ فارم کے لیے سائز بدلی کئی تصویریں۔ کسی بھی طرح بیچ ٹول اسے سنبھالتا ہے: تصویریں قطار میں ڈالیں، پہلے پلیٹ فارم کے لیے سائز طے کریں، ZIP ڈاؤن لوڈ کریں، پھر سائز بدلیں اور اسی قطار کو اگلے پلیٹ فارم کے لیے دوبارہ چلائیں۔</p>\n<p>مربع پوسٹ 1080 بہ 1080 چاہتی ہیں، کہانیاں 1080 بہ 1920 چاہتی ہیں، اور تھمب نیل 1280 بہ 720 چاہتے ہیں۔ وہ عدد پکسل فیلڈ میں لکھیں، کیونکہ بلک پری سیٹ سوشل کی بجائے ویب اور دکان سائز پورا کرتے ہیں۔ ہر دوبارہ چلانا اس پلیٹ فارم کے لیے تازہ ZIP بناتا ہے۔</p>\n<p>ہر تصویر میں موضوع کو مرکز میں اور کناروں سے دور رکھیں۔ پلیٹ فارم آپ کی تصویر کے اوپر بٹن اور کیپشن ڈالتے ہیں، اور کنارے کے قریب چہرہ انٹرفیس عنصر کے پیچھے چھپ سکتا ہے۔ پری سیٹ آپ کو فریم دیتا ہے، مگر آپ کی ترکیب طے کرتی ہے کہ اس میں کیا بچتا ہے۔</p>\n<h2 id=\"resize-on-your-phone\">اپنے فون پر بیچ سائز بدلیں</h2>\n<p>بلک ری سائزر موبائل براؤزر پر کام کرتا ہے، اور چھوٹا بیچ فون سے چلانا آسان ہے۔ فوٹو لائبریری سے اپ لوڈ کریں، حکمت عملی اور پری سیٹ چنیں، اور ZIP فون پر واپس ڈاؤن لوڈ کریں۔ یہ پوسٹ کرنے سے ٹھیک پہلے تصویروں کا سیٹ درست کرنے کو سوٹ کرتا ہے۔</p>\n<p>فون کے بیچ سائز اور گنتی میں معتدل رکھیں۔ بڑے کینوس زیادہ براؤزر میموری استعمال کرتے ہیں، اور فون میں ڈیسک ٹاپ سے کم میموری ہوتی ہے۔ فی طرف 4000 سے 6000 پکسل اور ایک وقت میں درجن تصویروں کے اندر رہنے سے موبائل پر بیچ ہموار رہتا ہے۔</p>\n<p>اگر فون کا بیچ سست لگے تو اسے آدھا تقسیم کریں اور دو چھوٹے بیچ چلائیں۔ ترتیبات ایک جیسی رہتی ہیں، نتائج ایک جیسے ہیں، اور ہر آدھا پورے فولڈر سے تیز مکمل ہوتا ہے۔ ZIP بعد میں جوڑے جا سکتے ہیں، یا الگ اپ لوڈ کیے جا سکتے ہیں۔</p>\n<h2 id=\"troubleshooting-batches\">بیچ مسائل کا حل</h2>\n<p>اگر کچھ تصویریں کھینچی ہوئی لگیں تو بیچ نے Stretch کے ساتھ Exact ابعاد استعمال کیے، یا پہلو تناسب مجبور کیا گیا۔ Fit Max کے ساتھ دوبارہ چلائیں، یا Exact کو Contain یا Cover پر بدلیں، اور دوبارہ ڈاؤن لوڈ سے پہلے پورٹریٹ کارڈ اور منظر کارڈ جانچیں۔</p>\n<p>اگر کچھ تصویریں دھندلی لگیں تو چھوٹے اصل کو شاید بڑا کیا گیا۔ یقین کریں کہ Do not enlarge smaller images چیک ہے، پھر دوبارہ چلائیں۔ اگر ماخذ خود کم ریزولوشن ہے تو اسے بڑا کرنے کی بجائے چھوٹے ہدف پر سائز بدلیں، اور وہ سائز قبول کریں جسے ماخذ سپورٹ کرتا ہے۔</p>\n<p>اگر ZIP میں فائل گم ہو تو جانچیں کہ وہ کارڈ ناکام ہوا یا ہٹایا گیا۔ 25 MB فی فائل حد سے زیادہ فائل پروسیس نہیں ہو گی، اور کوڑے دان آئیکن سے حذف شدہ کارڈ بیچ سے چلا گیا۔ گم شدہ فائل دوبارہ شامل کریں اور بیچ دوبارہ چلائیں۔</p>\n<h2 id=\"repeat-batches-and-workflow\">دہرائے جانے والے بیچ اور ورک فلو</h2>\n<p>کئی بیچ کام ہفتہ وار دہرائے جاتے ہیں: نئی مصنوعات، نئی پوسٹیں، نئی تصویریں۔ کام آنے والی ترتیبات کا نوٹ رکھیں، جیسے بلاگ کے لیے Fit Max 1200 اور دکان کے لیے Exact 1000 Cover۔ مختصر نوٹ اگلے بیچ کو تازہ فیصلے کی بجائے دو منٹ کا کام بنا دیتا ہے۔</p>\n<p>جب بیچ کو ایڈجسٹمنٹ چاہیے تو دوبارہ اپ لوڈ کیے بغیر ترتیبات ایڈجسٹ کریں اور دوبارہ چلائیں۔ فائلیں براؤزر میموری میں قطار میں رہتی ہیں، اس لیے حکمت عملی، سائز یا کوالٹی بدلنے اور Bulk Resize دوبارہ کلک کرنے سے سب کچھ فوراً دوبارہ پروسیس ہوتا ہے۔ اس سے تجربہ سستا بن جاتا ہے۔</p>\n<h2 id=\"quick-checklist\">فوری چیک لسٹ</h2>\n<p>فولڈر تیار کریں، حکمت عملی چنیں، سائز طے کریں، no-upscale تحفظ آن رکھیں، نتائج جانچیں، اور ZIP ڈاؤن لوڈ کریں۔ یہی پورا ورک فلو ہے، اور یہ پانچ تصویروں یا پچاس کے لیے کام کرتا ہے۔</p>\n<p>اسے <a href=\"/ur/bulk-tasveer-resize-karein/\">بلک تصویر ری سائزر</a> پر آزمائیں۔ تصورات کے لیے <a href=\"/ur/blog/bulk-tasveer-resizer-rehnumai/\">Bulk Image Resizer: Complete Guide</a> پڑھیں، اکیلی تصویروں کے لیے <a href=\"/ur/blog/tasveer-kaise-resize-karein/\">How to Resize an Image Online</a> دیکھیں، اور فی منزل سائز کے لیے <a href=\"/ur/blog/bulk-resize-presets-social-ecommerce-print/\">Bulk Resize Presets: Social, E-commerce and Print</a> دیکھیں۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"بڑے بیچ کو سائز بدلنے میں کتنا وقت لگتا ہے؟","answer":"یہ تصویروں کے سائز اور گنتی اور آپ کے آلے کی رفتار پر منحصر ہے، کیونکہ ساری پروسیسنگ آپ کے براؤزر میں مقامی طور پر ہوتی ہے۔ بیس عام تصویروں کا بیچ عام طور پر ایک منٹ سے کم میں مکمل ہوتا ہے۔ بہت بڑی تصویریں زیادہ وقت لیتی ہیں، اور لائیو پیش رفت کاؤنٹر Resizing (X/Y) دکھاتا ہے تاکہ آپ دیکھ سکیں کہ کتنا آگے ہے۔"},{"question":"اگر میرے بیچ میں ایک تصویر ناکام ہو جائے تو کیا ہو گا؟","answer":"باقی بیچ پروسیس جاری رکھتا ہے، اور صرف ناکام فائل ZIP سے باہر رہتی ہے۔ جانچیں کہ وہ فائل 25 MB فی فائل حد سے زیادہ ہے یا غیر سپورٹ فارمیٹ میں ہے، پھر اسے درست کریں اور نئے بیچ میں شامل کریں۔ پیش رفت کاؤنٹر اور نتیجہ کارڈ دکھاتے ہیں کہ کون سی فائلیں کامیاب مکمل ہوئیں۔"},{"question":"کیا بیچ مکمل ہونے کے بعد مزید تصویریں شامل کر سکتا ہوں؟","answer":"جی ہاں۔ کسی بھی وقت اپ لوڈ ڈراپ زون پر اضافی فائلیں گھسیٹیں اور وہ آپ کی فعال سائز بدلنے کی حکمت عملی کے ساتھ خود بخود پروسیس ہوتی ہیں، پھر حتمی Download All (ZIP) خلاصے میں شامل ہو جاتی ہیں۔ دیر سے آنے والوں کے لیے نیا بیچ شروع کرنے کی ضرورت نہیں۔"},{"question":"کیا بیچ سائز بدلنے کی تعداد پر کوئی حد ہے؟","answer":"نہیں۔ بیچ چلانے کی تعداد پر کوئی استعمال حد، کوئی اکاؤنٹ اور کوئی کوٹا نہیں۔ آپ جتنے فولڈر چاہیں، جتنی بار چاہیں سائز بدل سکتے ہیں، کیونکہ سب کچھ آپ کے براؤزر میں مقامی طور پر چلتا ہے اور خدمت کو فی بیچ کچھ خرچ نہیں ہوتا۔"},{"question":"کیا سائز بدلی تصویریں اپنے اصل فائل نام رکھتی ہیں؟","answer":"سائز بدلی فائلیں اصل پر مبنی صاف، پہچانی جانے والی نام رکھتی ہیں، ZIP آرکائیو میں ایک ساتھ پیک شدہ۔ اس سے ہر سائز بدلی فائل کو اس کے اصل سے ملانا آسان ہوتا ہے جب آپ انہیں دکان، بلاگ یا سوشل اکاؤنٹ میں اپ لوڈ کریں۔"},{"question":"پہلی آزمائش کے لیے بہترین بیچ سائز کیا ہے؟","answer":"پانچ سے دس تصویروں سے شروع کریں، تاکہ آپ حکمت عملی سیکھ سکیں اور نتائج تیزی سے جانچ سکیں۔ جب ترتیبات درست لگیں تو انہی ترتیبات کے ساتھ مکمل فولڈر چلائیں۔ چھوٹا آزمائشی بیچ غلط حکمت عملی یا خراب کوالٹی ترتیب کو پچاس تصویروں پر لاگو ہونے سے پہلے پکڑتا ہے۔"}];
